266	void DefaultBtAnnounce::announceStart() { ++trackers_; }
267	
268	void DefaultBtAnnounce::announceSuccess()
269	{
270	  trackers_ = 0;
271	  announceList_.announceSuccess();
272	}
273	
274	void DefaultBtAnnounce::announceFailure()
275	{
276	  trackers_ = 0;
277	  announceList_.announceFailure();
278	}
