280	bool DefaultBtAnnounce::isAllAnnounceFailed()
281	{
282	  return announceList_.allTiersFailed();
283	}
284	
285	void DefaultBtAnnounce::resetAnnounce()
286	{
287	  prevAnnounceTimer_ = global::wallclock();
288	  announceList_.resetTier();
289	}
290	
291	void DefaultBtAnnounce::processAnnounceResponse(
292	    const unsigned char* trackerResponse, size_t trackerResponseLength)
293	{
294	  A2_LOG_DEBUG("Now processing tracker response.");
295	  auto decodedValue = bencode2::decode(trackerResponse, trackerResponseLength);
296	  const Dict* dict = downcast<Dict>(decodedValue);
297	  if (!dict) {
298	    throw DL_ABORT_EX(MSG_NULL_TRACKER_RESPONSE);
299	  }
300	  const String* failure =
301	      downcast<String>(dict->get(BtAnnounce::FAILURE_REASON));
302	  if (failure) {
303	    throw DL_ABORT_EX(fmt(EX_TRACKER_FAILURE, failure->s().c_str()));
304	  }
305	  const String* warn = downcast<String>(dict->get(BtAnnounce::WARNING_MESSAGE));
306	  if (warn) {
307	    A2_LOG_WARN(fmt(MSG_TRACKER_WARNING_MESSAGE, warn->s().c_str()));
308	  }
309	  const String* tid = downcast<String>(dict->get(BtAnnounce::TRACKER_ID));
310	  if (tid) {
311	    trackerId_ = tid->s();
312	    A2_LOG_DEBUG(fmt("Tracker ID:%s", trackerId_.c_str()));
313	  }
314	  const Integer* ival = downcast<Integer>(dict->get(BtAnnounce::INTERVAL));
315	  if (ival && ival->i() > 0) {
316	    interval_ = std::chrono::seconds(ival->i());
317	    A2_LOG_DEBUG(fmt("Interval:%ld", static_cast<long int>(interval_.count())));
318	  }
319	  const Integer* mival = downcast<Integer>(dict->get(BtAnnounce::MIN_INTERVAL));
320	  if (mival && mival->i() > 0) {
321	    minInterval_ = std::chrono::seconds(mival->i());
322	    A2_LOG_DEBUG(
323	        fmt("Min interval:%ld", static_cast<long int>(minInterval_.count())));
324	    minInterval_ = std::min(minInterval_, interval_);
325	  }
326	  else {
327	    // Use interval as a minInterval if minInterval is not supplied.
328	    minInterval_ = interval_;
329	  }
330	  const Integer* comp = downcast<Integer>(dict->get(BtAnnounce::COMPLETE));
331	  if (comp && comp->i() >= 0) {
332	    complete_ = comp->i();
333	    A2_LOG_DEBUG(fmt("Complete:%d", complete_));
334	  }
335	  const Integer* incomp = downcast<Integer>(dict->get(BtAnnounce::INCOMPLETE));
336	  if (incomp && incomp->i() >= 0) {
337	    incomplete_ = incomp->i();
338	    A2_LOG_DEBUG(fmt("Incomplete:%d", incomplete_));
339	  }
340	  auto peerData = dict->get(BtAnnounce::PEERS);
341	  if (!peerData) {
342	    A2_LOG_INFO(MSG_NO_PEER_LIST_RECEIVED);
343	  }
344	  else {
345	    if (!btRuntime_->isHalt() && btRuntime_->lessThanMinPeers()) {
346	      std::vector<std::shared_ptr<Peer>> peers;
347	      bittorrent::extractPeer(peerData, AF_INET, std::back_inserter(peers));
348	      peerStorage_->addPeer(peers);
349	    }
350	  }
351	  auto peer6Data = dict->get(BtAnnounce::PEERS6);
352	  if (!peer6Data) {
353	    A2_LOG_INFO("No peers6 received.");
354	  }
355	  else {
356	    if (!btRuntime_->isHalt() && btRuntime_->lessThanMinPeers()) {
357	      std::vector<std::shared_ptr<Peer>> peers;
358	      bittorrent::extractPeer(peer6Data, AF_INET6, std::back_inserter(peers));
359	      peerStorage_->addPeer(peers);
360	    }
361	  }
362	}
363	
364	void DefaultBtAnnounce::processUDPTrackerResponse(
365	    const std::shared_ptr<UDPTrackerRequest>& req)
366	{
367	  const std::shared_ptr<UDPTrackerReply>& reply = req->reply;
368	  A2_LOG_DEBUG("Now processing UDP tracker response.");
369	  if (reply->interval > 0) {
370	    minInterval_ = std::chrono::seconds(reply->interval);
371	    A2_LOG_DEBUG(
372	        fmt("Min interval:%ld", static_cast<long int>(minInterval_.count())));
373	    interval_ = minInterval_;
374	  }
375	  complete_ = reply->seeders;
376	  A2_LOG_DEBUG(fmt("Complete:%d", reply->seeders));
377	  incomplete_ = reply->leechers;
378	  A2_LOG_DEBUG(fmt("Incomplete:%d", reply->leechers));
379	  if (!btRuntime_->isHalt() && btRuntime_->lessThanMinPeers()) {
380	    for (auto& elem : reply->peers) {
381	      peerStorage_->addPeer(std::make_shared<Peer>(elem.first, elem.second));
382	    }
383	  }
384	}
385	
386	bool DefaultBtAnnounce::noMoreAnnounce()
387	{
388	  return (trackers_ == 0 && btRuntime_->isHalt() &&
389	          !announceList_.countStoppedAllowedTier());
390	}
391	
392	void DefaultBtAnnounce::shuffleAnnounce() { announceList_.shuffle(); }
393	
394	void DefaultBtAnnounce::setRandomizer(Randomizer* randomizer)
395	{
396	  randomizer_ = randomizer;
397	}
398	
399	void DefaultBtAnnounce::setBtRuntime(
400	    const std::shared_ptr<BtRuntime>& btRuntime)
401	{
402	  btRuntime_ = btRuntime;
403	}
404	
405	void DefaultBtAnnounce::setPieceStorage(
406	    const std::shared_ptr<PieceStorage>& pieceStorage)
407	{
408	  pieceStorage_ = pieceStorage;
409	}
410	
411	void DefaultBtAnnounce::setPeerStorage(
412	    const std::shared_ptr<PeerStorage>& peerStorage)
413	{
414	  peerStorage_ = peerStorage;
415	}
416	
417	void DefaultBtAnnounce::overrideMinInterval(std::chrono::seconds interval)
418	{
419	  minInterval_ = std::move(interval);
420	}
421	
422	} // namespace aria2
