89	bool HTTPAnnRequest::issue(DownloadEngine* e)
90	{
91	  try {
92	    std::vector<std::unique_ptr<Command>> commands;
93	    rg_->createInitialCommand(commands, e);
94	    e->addCommand(std::move(commands));
95	    e->setNoWait(true);
96	    A2_LOG_DEBUG("added tracker request command");
97	    return true;
98	  }
99	  catch (RecoverableException& ex) {
100	    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, ex);
101	    return false;
102	  }
