105	bool HTTPAnnRequest::processResponse(
106	    const std::shared_ptr<BtAnnounce>& btAnnounce)
107	{
108	  try {
109	    std::stringstream strm;
110	    unsigned char data[2048];
111	    rg_->getPieceStorage()->getDiskAdaptor()->openFile();
112	    while (1) {
113	      ssize_t dataLength = rg_->getPieceStorage()->getDiskAdaptor()->readData(
114	          data, sizeof(data), strm.tellp());
115	      if (dataLength == 0) {
116	        break;
117	      }
118	      strm.write(reinterpret_cast<const char*>(data), dataLength);
119	    }
120	    std::string res = strm.str();
121	    btAnnounce->processAnnounceResponse(
122	        reinterpret_cast<const unsigned char*>(res.c_str()), res.size());
123	    return true;
124	  }
125	  catch (RecoverableException& e) {
126	    const auto& dctx = rg_->getDownloadContext();
127	    const auto& fe = dctx->getFirstFileEntry();
128	    auto uris = fe->getUris();
129	
130	    A2_LOG_ERROR_EX(fmt("GID#%s - Tracker request %s failed",
131	                        GroupId::toHex(rg_->getGID()).c_str(), uris[0].c_str()),
132	                    e);
133	    return false;
134	  }
135	}
