296	std::unique_ptr<AnnRequest>
297	TrackerWatcherCommand::createAnnounce(DownloadEngine* e)
298	{
299	  while (!btAnnounce_->isAllAnnounceFailed() &&
300	         btAnnounce_->isAnnounceReady()) {
301	    std::string uri = btAnnounce_->getAnnounceUrl();
302	    uri_split_result res;
303	    memset(&res, 0, sizeof(res));
304	    if (uri_split(&res, uri.c_str()) == 0) {
305	      // Without UDP tracker support, send it to normal tracker flow
306	      // and make it fail.
307	      std::unique_ptr<AnnRequest> treq;
308	      if (udpTrackerClient_ &&
309	          uri::getFieldString(res, USR_SCHEME, uri.c_str()) == "udp") {
310	        uint16_t localPort;
311	        localPort = e->getBtRegistry()->getTcpPort();
312	        treq =
313	            createUDPAnnRequest(uri::getFieldString(res, USR_HOST, uri.c_str()),
314	                                res.port, localPort);
315	      }
316	      else {
317	        treq = createHTTPAnnRequest(btAnnounce_->getAnnounceUrl());
318	      }
319	      btAnnounce_->announceStart(); // inside it, trackers++.
320	      return treq;
321	    }
322	    else {
323	      btAnnounce_->announceFailure();
324	    }
325	  }
326	  if (btAnnounce_->isAllAnnounceFailed()) {
327	    btAnnounce_->resetAnnounce();
328	  }
329	  return nullptr;
330	}
