361	std::unique_ptr<AnnRequest>
362	TrackerWatcherCommand::createHTTPAnnRequest(const std::string& uri)
363	{
364	  std::vector<std::string> uris;
365	  uris.push_back(uri);
366	  auto option = util::copy(getOption());
367	  auto rg = make_unique<RequestGroup>(GroupId::create(), option);
368	  if (backupTrackerIsAvailable(requestGroup_->getDownloadContext())) {
369	    A2_LOG_DEBUG("This is multi-tracker announce.");
370	  }
371	  else {
372	    A2_LOG_DEBUG("This is single-tracker announce.");
373	  }
374	  rg->setNumConcurrentCommand(1);
375	  // If backup tracker is available, try 2 times for each tracker
376	  // and if they all fails, then try next one.
377	  option->put(PREF_MAX_TRIES, "2");
378	  // TODO When dry-run mode becomes available in BitTorrent, set
379	  // PREF_DRY_RUN=false too.
380	  option->put(PREF_USE_HEAD, A2_V_FALSE);
381	  // Setting tracker timeouts
382	  rg->setTimeout(
383	      std::chrono::seconds(option->getAsInt(PREF_BT_TRACKER_TIMEOUT)));
384	  option->put(PREF_CONNECT_TIMEOUT,
385	              option->get(PREF_BT_TRACKER_CONNECT_TIMEOUT));
386	  option->put(PREF_REUSE_URI, A2_V_FALSE);
387	  option->put(PREF_SELECT_LEAST_USED_HOST, A2_V_FALSE);
388	  auto dctx = std::make_shared<DownloadContext>(
389	      option->getAsInt(PREF_PIECE_LENGTH), 0, "[tracker.announce]");
390	  dctx->getFileEntries().front()->setUris(uris);
391	  rg->setDownloadContext(dctx);
392	  auto dwf = std::make_shared<ByteArrayDiskWriterFactory>();
393	  rg->setDiskWriterFactory(dwf);
