57	
58	namespace aria2 {
59	
60	DefaultBtAnnounce::DefaultBtAnnounce(DownloadContext* downloadContext,
61	                                     const Option* option)
62	    : downloadContext_{downloadContext},
63	      trackers_(0),
64	      prevAnnounceTimer_(Timer::zero()),
65	      interval_(DEFAULT_ANNOUNCE_INTERVAL),
66	      minInterval_(DEFAULT_ANNOUNCE_INTERVAL),
67	      userDefinedInterval_(0_s),
68	      complete_(0),
69	      incomplete_(0),
70	      announceList_(bittorrent::getTorrentAttrs(downloadContext)->announceList),
71	      option_(option),
72	      randomizer_(SimpleRandomizer::getInstance().get()),
73	      tcpPort_(0)
74	{
75	}
76	
77	DefaultBtAnnounce::~DefaultBtAnnounce() = default;
78	
79	bool DefaultBtAnnounce::isDefaultAnnounceReady()
80	{
81	  return (trackers_ == 0 &&
82	          prevAnnounceTimer_.difference(global::wallclock()) >=
83	              (userDefinedInterval_.count() == 0 ? minInterval_
84	                                                 : userDefinedInterval_) &&
85	          !announceList_.allTiersFailed());
86	}
87	
88	bool DefaultBtAnnounce::isStoppedAnnounceReady()
89	{
90	  return (trackers_ == 0 && btRuntime_->isHalt() &&
91	          announceList_.countStoppedAllowedTier());
92	}
93	
94	bool DefaultBtAnnounce::isCompletedAnnounceReady()
95	{
96	  return (trackers_ == 0 && pieceStorage_->allDownloadFinished() &&
97	          announceList_.countCompletedAllowedTier());
98	}
99	
100	bool DefaultBtAnnounce::isAnnounceReady()
101	{
102	  return isStoppedAnnounceReady() || isCompletedAnnounceReady() ||
103	         isDefaultAnnounceReady();
104	}
105	
106	namespace {
107	bool uriHasQuery(const std::string& uri)
108	{
109	  uri_split_result us;
110	  if (uri_split(&us, uri.c_str()) == 0) {
111	    return (us.field_set & (1 << USR_QUERY)) && us.fields[USR_QUERY].len > 0;
112	  }
113	  else {
114	    return false;
115	  }
116	}
117	} // namespace
118	
119	bool DefaultBtAnnounce::adjustAnnounceList()
120	{
121	  if (isStoppedAnnounceReady()) {
122	    if (!announceList_.currentTierAcceptsStoppedEvent()) {
123	      announceList_.moveToStoppedAllowedTier();
124	    }
125	    announceList_.setEvent(AnnounceTier::STOPPED);
126	  }
127	  else if (isCompletedAnnounceReady()) {
128	    if (!announceList_.currentTierAcceptsCompletedEvent()) {
129	      announceList_.moveToCompletedAllowedTier();
130	    }
131	    announceList_.setEvent(AnnounceTier::COMPLETED);
132	  }
133	  else if (isDefaultAnnounceReady()) {
134	    // If download completed before "started" event is sent to a tracker,
135	    // we change the event to something else to prevent us from
136	    // sending "completed" event.
137	    if (pieceStorage_->allDownloadFinished() &&
138	        announceList_.getEvent() == AnnounceTier::STARTED) {
139	      announceList_.setEvent(AnnounceTier::STARTED_AFTER_COMPLETION);
140	    }
141	  }
142	  else {
143	    return false;
144	  }
145	  return true;
146	}
147	
148	std::string DefaultBtAnnounce::getAnnounceUrl()
149	{
150	  if (!adjustAnnounceList()) {
151	    return A2STR::NIL;
152	  }
153	  int numWant = 50;
154	  if (!btRuntime_->lessThanMinPeers() || btRuntime_->isHalt()) {
155	    numWant = 0;
156	  }
157	  NetStat& stat = downloadContext_->getNetStat();
158	  int64_t left =
159	      pieceStorage_->getTotalLength() - pieceStorage_->getCompletedLength();
160	  // Use last 8 bytes of peer ID as a key
161	  const size_t keyLen = 8;
162	  std::string uri = announceList_.getAnnounce();
163	  uri += uriHasQuery(uri) ? "&" : "?";
164	  uri +=
165	      fmt("info_hash=%s&"
166	          "peer_id=%s&"
167	          "uploaded=%" PRId64 "&"
168	          "downloaded=%" PRId64 "&"
169	          "left=%" PRId64 "&"
170	          "compact=1&"
171	          "key=%s&"
172	          "numwant=%d&"
173	          "no_peer_id=1",
174	          util::percentEncode(bittorrent::getInfoHash(downloadContext_),
175	                              INFO_HASH_LENGTH)
176	              .c_str(),
177	          util::percentEncode(bittorrent::getStaticPeerId(), PEER_ID_LENGTH)
178	              .c_str(),
179	          stat.getSessionUploadLength(), stat.getSessionDownloadLength(), left,
180	          util::percentEncode(
181	              bittorrent::getStaticPeerId() + PEER_ID_LENGTH - keyLen, keyLen)
182	              .c_str(),
183	          numWant);
184	  if (tcpPort_) {
185	    uri += fmt("&port=%u", tcpPort_);
186	  }
187	  const char* event = announceList_.getEventString();
188	  if (event[0]) {
189	    uri += "&event=";
190	    uri += event;
191	  }
192	  if (!trackerId_.empty()) {
193	    uri += "&trackerid=";
194	    uri += util::percentEncode(trackerId_);
195	  }
196	  if (option_->getAsBool(PREF_BT_FORCE_ENCRYPTION) ||
197	      option_->getAsBool(PREF_BT_REQUIRE_CRYPTO)) {
198	    uri += "&requirecrypto=1";
199	  }
200	  else {
201	    uri += "&supportcrypto=1";
202	  }
203	  if (!option_->blank(PREF_BT_EXTERNAL_IP)) {
204	    uri += "&ip=";
205	    uri += option_->get(PREF_BT_EXTERNAL_IP);
206	  }
207	  return uri;
208	}
209	
210	std::shared_ptr<UDPTrackerRequest> DefaultBtAnnounce::createUDPTrackerRequest(
211	    const std::string& remoteAddr, uint16_t remotePort, uint16_t localPort)
212	{
213	  if (!adjustAnnounceList()) {
214	    return nullptr;
215	  }
216	  NetStat& stat = downloadContext_->getNetStat();
217	  int64_t left =
218	      pieceStorage_->getTotalLength() - pieceStorage_->getCompletedLength();
219	  auto req = std::make_shared<UDPTrackerRequest>();
220	  req->remoteAddr = remoteAddr;
221	  req->remotePort = remotePort;
222	  req->action = UDPT_ACT_ANNOUNCE;
223	  req->infohash = bittorrent::getTorrentAttrs(downloadContext_)->infoHash;
224	  const unsigned char* peerId = bittorrent::getStaticPeerId();
225	  req->peerId.assign(peerId, peerId + PEER_ID_LENGTH);
226	  req->downloaded = stat.getSessionDownloadLength();
227	  req->left = left;
228	  req->uploaded = stat.getSessionUploadLength();
229	  switch (announceList_.getEvent()) {
230	  case AnnounceTier::STARTED:
231	  case AnnounceTier::STARTED_AFTER_COMPLETION:
232	    req->event = UDPT_EVT_STARTED;
233	    break;
234	  case AnnounceTier::STOPPED:
235	    req->event = UDPT_EVT_STOPPED;
236	    break;
237	  case AnnounceTier::COMPLETED:
238	    req->event = UDPT_EVT_COMPLETED;
239	    break;
240	  default:
241	    req->event = 0;
242	  }
243	  if (!option_->blank(PREF_BT_EXTERNAL_IP)) {
244	    unsigned char dest[16];
245	    if (net::getBinAddr(dest, option_->get(PREF_BT_EXTERNAL_IP)) == 4) {
246	      memcpy(&req->ip, dest, 4);
247	    }
248	    else {
249	      req->ip = 0;
250	    }
251	  }
252	  else {
253	    req->ip = 0;
254	  }
255	  req->key = randomizer_->getRandomNumber(INT32_MAX);
256	  int numWant = 50;
257	  if (!btRuntime_->lessThanMinPeers() || btRuntime_->isHalt()) {
258	    numWant = 0;
259	  }
260	  req->numWant = numWant;
261	  req->port = localPort;
262	  req->extensions = 0;
263	  return req;
264	}
