208	
209	bool TrackerWatcherCommand::execute()
210	{
211	  if (requestGroup_->isForceHaltRequested()) {
212	    if (!trackerRequest_) {
213	      return true;
214	    }
215	    else if (trackerRequest_->stopped() || trackerRequest_->success()) {
216	      return true;
217	    }
218	    else {
219	      trackerRequest_->stop(e_);
220	      e_->setRefreshInterval(std::chrono::milliseconds(0));
221	      e_->addCommand(std::unique_ptr<Command>(this));
222	      return false;
223	    }
224	  }
225	  if (btAnnounce_->noMoreAnnounce()) {
226	    A2_LOG_DEBUG("no more announce");
227	    return true;
228	  }
229	  if (!trackerRequest_) {
230	    trackerRequest_ = createAnnounce(e_);
231	    if (trackerRequest_) {
232	      trackerRequest_->issue(e_);
233	      A2_LOG_DEBUG("tracker request created");
234	    }
235	  }
236	  else if (trackerRequest_->stopped()) {
237	    // We really want to make sure that tracker request has finished
238	    // by checking getNumCommand() == 0. Because we reset
239	    // trackerRequestGroup_, if it is still used in other Command, we
240	    // will get Segmentation fault.
241	    if (trackerRequest_->success()) {
242	      if (trackerRequest_->processResponse(btAnnounce_)) {
243	        btAnnounce_->announceSuccess();
244	        btAnnounce_->resetAnnounce();
245	        addConnection();
246	      }
247	      else {
248	        btAnnounce_->announceFailure();
249	        if (btAnnounce_->isAllAnnounceFailed()) {
250	          btAnnounce_->resetAnnounce();
251	        }
252	      }
253	      trackerRequest_.reset();
254	    }
255	    else {
256	      // handle errors here
257	      btAnnounce_->announceFailure(); // inside it, trackers = 0.
258	      trackerRequest_.reset();
259	      if (btAnnounce_->isAllAnnounceFailed()) {
260	        btAnnounce_->resetAnnounce();
261	      }
262	    }
263	  }
264	
265	  if (!trackerRequest_ && btAnnounce_->noMoreAnnounce()) {
266	    A2_LOG_DEBUG("no more announce");
267	    return true;
268	  }
269	
270	  e_->addCommand(std::unique_ptr<Command>(this));
271	  return false;
272	}
273	
274	void TrackerWatcherCommand::addConnection()
275	{
276	  while (!btRuntime_->isHalt() && btRuntime_->lessThanMinPeers()) {
277	    if (!peerStorage_->isPeerAvailable()) {
278	      break;
279	    }
280	    cuid_t ncuid = e_->newCUID();
281	    std::shared_ptr<Peer> peer = peerStorage_->checkoutPeer(ncuid);
282	    // sanity check
283	    if (!peer) {
284	      break;
285	    }
286	    auto command = make_unique<PeerInitiateConnectionCommand>(
287	        ncuid, requestGroup_, peer, e_, btRuntime_);
288	    command->setPeerStorage(peerStorage_);
289	    command->setPieceStorage(pieceStorage_);
290	    e_->addCommand(std::move(command));
291	    A2_LOG_DEBUG(fmt("CUID#%" PRId64 " - Adding new command CUID#%" PRId64 "",
292	                     getCuid(), peer->usedBy()));
293	  }
294	}
