332	std::unique_ptr<AnnRequest>
333	TrackerWatcherCommand::createUDPAnnRequest(const std::string& host,
334	                                           uint16_t port, uint16_t localPort)
335	{
336	  auto req = btAnnounce_->createUDPTrackerRequest(host, port, localPort);
337	  req->user_data = this;
338	
339	  return make_unique<UDPAnnRequest>(std::move(req));
