343	bool backupTrackerIsAvailable(const std::shared_ptr<DownloadContext>& context)
344	{
345	  auto torrentAttrs = bittorrent::getTorrentAttrs(context);
346	  if (torrentAttrs->announceList.size() >= 2) {
347	    return true;
348	  }
349	  if (torrentAttrs->announceList.empty()) {
350	    return false;
351	  }
352	  if (torrentAttrs->announceList[0].size() >= 2) {
353	    return true;
354	  }
355	  else {
356	    return false;
357	  }
358	}
