112	namespace {
113	struct CollectAddrPortMatch {
114	  bool operator()(const std::shared_ptr<UDPTrackerRequest>& req) const
115	  {
116	    if (req->remoteAddr == remoteAddr && req->remotePort == remotePort) {
117	      dest.push_back(req);
118	      return true;
119	    }
120	    else {
121	      return false;
122	    }
123	  }
124	  std::vector<std::shared_ptr<UDPTrackerRequest>>& dest;
125	  std::string remoteAddr;
126	  uint16_t remotePort;
127	  CollectAddrPortMatch(std::vector<std::shared_ptr<UDPTrackerRequest>>& dest,
128	                       std::string remoteAddr, uint16_t remotePort)
