371	void UDPTrackerClient::addRequest(const std::shared_ptr<UDPTrackerRequest>& req)
372	{
373	  req->state = UDPT_STA_PENDING;
374	  req->error = UDPT_ERR_SUCCESS;
375	  pendingRequests_.push_back(req);
376	}
