378	namespace {
379	struct TimeoutCheck {
380	  bool operator()(const std::shared_ptr<UDPTrackerRequest>& req) const
381	  {
382	    auto t = req->dispatched.difference(now);
383	    if (req->failCount == 0) {
384	      if (t >= 5_s) {
385	        switch (req->action) {
386	        case UDPT_ACT_CONNECT:
387	          A2_LOG_INFO(fmt("UDPT resend CONNECT to %s:%u transaction_id=%08x",
388	                          req->remoteAddr.c_str(), req->remotePort,
389	                          req->transactionId));
390	          break;
391	        case UDPT_ACT_ANNOUNCE:
392	          A2_LOG_INFO(fmt("UDPT resend ANNOUNCE to %s:%u transaction_id=%08x, "
393	                          "connection_id=%016" PRIx64 ", event=%s, infohash=%s",
394	                          req->remoteAddr.c_str(), req->remotePort,
395	                          req->transactionId, req->connectionId,
396	                          getUDPTrackerEventStr(req->event),
397	                          util::toHex(req->infohash).c_str()));
398	          break;
399	        default:
400	          // unreachable
401	          assert(0);
402	        }
403	        ++req->failCount;
404	        dest.push_back(req);
405	        return true;
406	      }
407	      else {
408	        return false;
409	      }
410	    }
411	    else {
412	      if (t >= 10_s) {
413	        switch (req->action) {
414	        case UDPT_ACT_CONNECT:
415	          A2_LOG_INFO(fmt("UDPT timeout CONNECT to %s:%u transaction_id=%08x",
416	                          req->remoteAddr.c_str(), req->remotePort,
417	                          req->transactionId));
418	          client->failConnect(req->remoteAddr, req->remotePort,
419	                              UDPT_ERR_TIMEOUT);
420	          break;
421	        case UDPT_ACT_ANNOUNCE:
422	          A2_LOG_INFO(fmt("UDPT timeout ANNOUNCE to %s:%u transaction_id=%08x, "
423	                          "connection_id=%016" PRIx64 ", event=%s, infohash=%s",
424	                          req->remoteAddr.c_str(), req->remotePort,
425	                          req->transactionId, req->connectionId,
426	                          getUDPTrackerEventStr(req->event),
427	                          util::toHex(req->infohash).c_str()));
428	          break;
429	        default:
430	          // unreachable
431	          assert(0);
432	        }
433	        ++req->failCount;
434	        req->state = UDPT_STA_COMPLETE;
435	        req->error = UDPT_ERR_TIMEOUT;
436	        return true;
437	      }
438	      else {
439	        return false;
440	      }
441	    }
442	  }
443	  std::vector<std::shared_ptr<UDPTrackerRequest>>& dest;
444	  UDPTrackerClient* client;
445	  const Timer& now;
446	  TimeoutCheck(std::vector<std::shared_ptr<UDPTrackerRequest>>& dest,
447	               UDPTrackerClient* client, const Timer& now)
448	      : dest(dest), client(client), now(now)
449	  {
450	  }
451	};
452	} // namespace
453	
454	void UDPTrackerClient::handleTimeout(const Timer& now)
455	{
456	  std::vector<std::shared_ptr<UDPTrackerRequest>> dest;
457	  inflightRequests_.erase(std::remove_if(inflightRequests_.begin(),
458	                                         inflightRequests_.end(),
459	                                         TimeoutCheck(dest, this, now)),
460	                          inflightRequests_.end());
461	  pendingRequests_.insert(pendingRequests_.begin(), dest.begin(), dest.end());
462	}
463	
464	std::shared_ptr<UDPTrackerRequest>
465	UDPTrackerClient::findInflightRequest(const std::string& remoteAddr,
466	                                      uint16_t remotePort,
467	                                      uint32_t transactionId, bool remove)
468	{
469	  std::shared_ptr<UDPTrackerRequest> res;
470	  for (auto i = inflightRequests_.begin(), eoi = inflightRequests_.end();
471	       i != eoi; ++i) {
472	    if ((*i)->remoteAddr == remoteAddr && (*i)->remotePort == remotePort &&
473	        (*i)->transactionId == transactionId) {
474	      res = *i;
475	      if (remove) {
476	        inflightRequests_.erase(i);
477	      }
478	      break;
479	    }
480	  }
481	  return res;
482	}
483	
484	UDPTrackerConnection*
485	UDPTrackerClient::getConnectionId(const std::string& remoteAddr,
486	                                  uint16_t remotePort, const Timer& now)
487	{
488	  auto i = connectionIdCache_.find(std::make_pair(remoteAddr, remotePort));
489	  if (i == connectionIdCache_.end()) {
490	    return nullptr;
491	  }
492	  if ((*i).second.state == UDPT_CST_CONNECTED &&
493	      (*i).second.lastUpdated.difference(now) > 1_min) {
494	    connectionIdCache_.erase(i);
495	    return nullptr;
496	  }
497	  else {
498	    return &(*i).second;
499	  }
500	}
