502	namespace {
503	struct FailConnectDelete {
504	  bool operator()(const std::shared_ptr<UDPTrackerRequest>& req) const
505	  {
506	    if (req->action == UDPT_ACT_ANNOUNCE && req->remoteAddr == remoteAddr &&
507	        req->remotePort == remotePort) {
508	      A2_LOG_INFO(
509	          fmt("Force fail infohash=%s", util::toHex(req->infohash).c_str()));
510	      req->state = UDPT_STA_COMPLETE;
511	      req->error = error;
512	      return true;
513	    }
514	    else {
515	      return false;
516	    }
517	  }
518	  std::string remoteAddr;
519	  uint16_t remotePort;
520	  int error;
521	  FailConnectDelete(std::string remoteAddr, uint16_t remotePort, int error)
522	      : remoteAddr(std::move(remoteAddr)), remotePort(remotePort), error(error)
523	  {
524	  }
525	};
526	} // namespace
527	
528	void UDPTrackerClient::failConnect(const std::string& remoteAddr,
529	                                   uint16_t remotePort, int error)
530	{
531	  connectionIdCache_.erase(std::make_pair(remoteAddr, remotePort));
532	  // Fail all requests which are waiting for connection ID of the host.
533	  connectRequests_.erase(
534	      std::remove_if(connectRequests_.begin(), connectRequests_.end(),
535	                     FailConnectDelete(remoteAddr, remotePort, error)),
536	      connectRequests_.end());
537	  pendingRequests_.erase(
538	      std::remove_if(pendingRequests_.begin(), pendingRequests_.end(),
539	                     FailConnectDelete(remoteAddr, remotePort, error)),
540	      pendingRequests_.end());
541	}
542	
543	void UDPTrackerClient::failAll()
544	{
545	  int error = UDPT_ERR_SHUTDOWN;
546	  failRequest(inflightRequests_.begin(), inflightRequests_.end(), error);
547	  failRequest(pendingRequests_.begin(), pendingRequests_.end(), error);
548	  failRequest(connectRequests_.begin(), connectRequests_.end(), error);
549	}
550	
551	void UDPTrackerClient::increaseWatchers() { ++numWatchers_; }
552	
553	void UDPTrackerClient::decreaseWatchers() { --numWatchers_; }
554	
555	ssize_t createUDPTrackerConnect(unsigned char* data, size_t length,
556	                                std::string& remoteAddr, uint16_t& remotePort,
557	                                const std::shared_ptr<UDPTrackerRequest>& req)
558	{
559	  assert(length >= 16);
560	  remoteAddr = req->remoteAddr;
561	  remotePort = req->remotePort;
562	  bittorrent::setLLIntParam(data, UDPT_INITIAL_CONNECTION_ID);
563	  bittorrent::setIntParam(data + 8, req->action);
564	  bittorrent::setIntParam(data + 12, req->transactionId);
565	  return 16;
566	}
567	
568	ssize_t createUDPTrackerAnnounce(unsigned char* data, size_t length,
569	                                 std::string& remoteAddr, uint16_t& remotePort,
570	                                 const std::shared_ptr<UDPTrackerRequest>& req)
571	{
572	  assert(length >= 100);
573	  remoteAddr = req->remoteAddr;
574	  remotePort = req->remotePort;
575	  bittorrent::setLLIntParam(data, req->connectionId);
576	  bittorrent::setIntParam(data + 8, req->action);
577	  bittorrent::setIntParam(data + 12, req->transactionId);
578	  memcpy(data + 16, req->infohash.c_str(), req->infohash.size());
579	  memcpy(data + 36, req->peerId.c_str(), req->peerId.size());
580	  bittorrent::setLLIntParam(data + 56, req->downloaded);
581	  bittorrent::setLLIntParam(data + 64, req->left);
582	  bittorrent::setLLIntParam(data + 72, req->uploaded);
583	  bittorrent::setIntParam(data + 80, req->event);
584	  // ip is already network-byte order
585	  memcpy(data + 84, &req->ip, sizeof(req->ip));
586	  bittorrent::setIntParam(data + 88, req->key);
587	  bittorrent::setIntParam(data + 92, req->numWant);
588	  bittorrent::setShortIntParam(data + 96, req->port);
589	  // extensions is always 0
590	  bittorrent::setShortIntParam(data + 98, 0);
591	  return 100;
592	}
593	
594	const char* getUDPTrackerActionStr(int action)
595	{
596	  switch (action) {
597	  case UDPT_ACT_CONNECT:
598	    return "CONNECT";
599	  case UDPT_ACT_ANNOUNCE:
600	    return "ANNOUNCE";
601	  case UDPT_ACT_ERROR:
602	    return "ERROR";
603	  default:
604	    return "(unknown)";
605	  }
606	}
607	
608	const char* getUDPTrackerEventStr(int event)
609	{
610	  switch (event) {
611	  case UDPT_EVT_NONE:
612	    return "NONE";
613	  case UDPT_EVT_COMPLETED:
614	    return "COMPLETED";
615	  case UDPT_EVT_STARTED:
616	    return "STARTED";
617	  case UDPT_EVT_STOPPED:
618	    return "STOPPED";
619	  default:
620	    return "(unknown)";
621	  }
622	}
