135	int UDPTrackerClient::receiveReply(std::shared_ptr<UDPTrackerRequest>& recvReq,
136	                                   const unsigned char* data, size_t length,
137	                                   const std::string& remoteAddr,
138	                                   uint16_t remotePort, const Timer& now)
139	{
140	  int32_t action = bittorrent::getIntParam(data, 0);
141	  switch (action) {
142	  case UDPT_ACT_CONNECT: {
143	    if (length != 16) {
144	      logInvalidLength(remoteAddr, remotePort, action, 16, length);
145	      return -1;
146	    }
147	    auto transactionId = bittorrent::getIntParam(data, 4);
148	    std::shared_ptr<UDPTrackerRequest> req =
149	        findInflightRequest(remoteAddr, remotePort, transactionId, true);
150	    if (!req) {
151	      logInvalidTransaction(remoteAddr, remotePort, action, transactionId);
152	      return -1;
153	    }
154	
155	    auto connectionId = bittorrent::getLLIntParam(data, 8);
156	    A2_LOG_INFO(
157	        fmt("UDPT received CONNECT reply from %s:%u transaction_id=%08x,"
158	            "connection_id=%016" PRIx64,
159	            remoteAddr.c_str(), remotePort, transactionId, connectionId));
160	    UDPTrackerConnection c(UDPT_CST_CONNECTED, connectionId, now);
161	    connectionIdCache_[std::make_pair(remoteAddr, remotePort)] = c;
162	    // Now we have connection ID, push requests which are waiting for
163	    // it.
164	    std::vector<std::shared_ptr<UDPTrackerRequest>> reqs;
165	    connectRequests_.erase(
166	        std::remove_if(connectRequests_.begin(), connectRequests_.end(),
167	                       CollectAddrPortMatch(reqs, remoteAddr, remotePort)),
168	        connectRequests_.end());
169	    pendingRequests_.insert(pendingRequests_.begin(), reqs.begin(), reqs.end());
170	
171	    recvReq = std::move(req);
172	
173	    break;
174	  }
175	  case UDPT_ACT_ANNOUNCE: {
176	    if (length < 20) {
177	      logTooShortLength(remoteAddr, remotePort, action, 20, length);
178	      return -1;
179	    }
180	    auto transactionId = bittorrent::getIntParam(data, 4);
181	    std::shared_ptr<UDPTrackerRequest> req =
182	        findInflightRequest(remoteAddr, remotePort, transactionId, true);
183	    if (!req) {
184	      logInvalidTransaction(remoteAddr, remotePort, action, transactionId);
185	      return -1;
186	    }
187	    req->state = UDPT_STA_COMPLETE;
188	
189	    req->reply = std::make_shared<UDPTrackerReply>();
190	    req->reply->action = action;
191	    req->reply->transactionId = transactionId;
192	    req->reply->interval = bittorrent::getIntParam(data, 8);
193	    req->reply->leechers = bittorrent::getIntParam(data, 12);
194	    req->reply->seeders = bittorrent::getIntParam(data, 16);
195	
196	    int numPeers = 0;
197	    for (size_t i = 20; i < length; i += 6) {
198	      std::pair<std::string, uint16_t> hostport =
199	          bittorrent::unpackcompact(data + i, AF_INET);
200	      if (!hostport.first.empty()) {
201	        req->reply->peers.push_back(hostport);
202	        ++numPeers;
203	      }
204	    }
205	
206	    A2_LOG_INFO(
207	        fmt("UDPT received ANNOUNCE reply from %s:%u transaction_id=%08x,"
208	            "connection_id=%016" PRIx64 ", event=%s, infohash=%s, "
209	            "interval=%d, leechers=%d, "
210	            "seeders=%d, num_peers=%d",
211	            remoteAddr.c_str(), remotePort, transactionId, req->connectionId,
212	            getUDPTrackerEventStr(req->event),
213	            util::toHex(req->infohash).c_str(), req->reply->interval,
214	            req->reply->leechers, req->reply->seeders, numPeers));
215	
216	    recvReq = std::move(req);
217	
218	    break;
219	  }
220	  case UDPT_ACT_ERROR: {
221	    if (length < 8) {
222	      logTooShortLength(remoteAddr, remotePort, action, 8, length);
223	      return -1;
224	    }
225	    auto transactionId = bittorrent::getIntParam(data, 4);
226	    std::shared_ptr<UDPTrackerRequest> req =
227	        findInflightRequest(remoteAddr, remotePort, transactionId, true);
228	    if (!req) {
229	      logInvalidTransaction(remoteAddr, remotePort, action, transactionId);
230	      return -1;
231	    }
232	    std::string errorString(data + 8, data + length);
233	    errorString = util::encodeNonUtf8(errorString);
234	
235	    req->state = UDPT_STA_COMPLETE;
236	    req->error = UDPT_ERR_TRACKER;
237	
238	    A2_LOG_INFO(fmt("UDPT received ERROR reply from %s:%u transaction_id=%08x,"
239	                    "connection_id=%016" PRIx64 ", action=%d, error_string=%s",
240	                    remoteAddr.c_str(), remotePort, transactionId,
241	                    req->connectionId, action, errorString.c_str()));
242	    if (req->action == UDPT_ACT_CONNECT) {
243	      failConnect(req->remoteAddr, req->remotePort, UDPT_ERR_TRACKER);
244	    }
245	
246	    recvReq = std::move(req);
247	
248	    break;
249	  }
250	  case UDPT_ACT_SCRAPE:
251	    A2_LOG_INFO(fmt("unexpected scrape action reply from %s:%u",
252	                    remoteAddr.c_str(), remotePort));
253	    return -1;
254	  default:
255	    A2_LOG_INFO(
256	        fmt("unknown action reply from %s:%u", remoteAddr.c_str(), remotePort));
257	    return -1;
258	  }
259	  return 0;
260	}
