262	ssize_t UDPTrackerClient::createRequest(unsigned char* data, size_t length,
263	                                        std::string& remoteAddr,
264	                                        uint16_t& remotePort, const Timer& now)
265	{
266	  if (pendingRequests_.empty()) {
267	    return -1;
268	  }
269	  while (!pendingRequests_.empty()) {
270	    const std::shared_ptr<UDPTrackerRequest>& req = pendingRequests_.front();
271	    if (req->action == UDPT_ACT_CONNECT) {
272	      ssize_t rv;
273	      rv = createUDPTrackerConnect(data, length, remoteAddr, remotePort, req);
274	      return rv;
275	    }
276	    UDPTrackerConnection* c =
277	        getConnectionId(req->remoteAddr, req->remotePort, now);
278	    if (!c) {
279	      auto creq = std::make_shared<UDPTrackerRequest>();
280	      creq->action = UDPT_ACT_CONNECT;
281	      creq->remoteAddr = req->remoteAddr;
282	      creq->remotePort = req->remotePort;
283	      creq->transactionId = generateTransactionId();
284	      pendingRequests_.push_front(creq);
285	      ssize_t rv;
286	      rv = createUDPTrackerConnect(data, length, remoteAddr, remotePort, creq);
287	      return rv;
288	    }
289	    if (c->state == UDPT_CST_CONNECTING) {
290	      connectRequests_.push_back(req);
291	      pendingRequests_.pop_front();
292	      continue;
293	    }
294	    req->connectionId = c->connectionId;
295	    req->transactionId = generateTransactionId();
296	    ssize_t rv;
297	    rv = createUDPTrackerAnnounce(data, length, remoteAddr, remotePort, req);
298	    return rv;
299	  }
300	  return -1;
301	}
