303	void UDPTrackerClient::requestSent(const Timer& now)
304	{
305	  if (pendingRequests_.empty()) {
306	    A2_LOG_WARN("pendingRequests_ is empty");
307	    return;
308	  }
309	  const std::shared_ptr<UDPTrackerRequest>& req = pendingRequests_.front();
310	  switch (req->action) {
311	  case UDPT_ACT_CONNECT:
312	    A2_LOG_INFO(fmt("UDPT sent CONNECT to %s:%u transaction_id=%08x",
313	                    req->remoteAddr.c_str(), req->remotePort,
314	                    req->transactionId));
315	    break;
316	  case UDPT_ACT_ANNOUNCE:
317	    A2_LOG_INFO(fmt("UDPT sent ANNOUNCE to %s:%u transaction_id=%08x, "
318	                    "connection_id=%016" PRIx64 ", event=%s, infohash=%s",
319	                    req->remoteAddr.c_str(), req->remotePort,
320	                    req->transactionId, req->connectionId,
321	                    getUDPTrackerEventStr(req->event),
322	                    util::toHex(req->infohash).c_str()));
323	    break;
324	  default:
325	    // unreachable
326	    assert(0);
327	  }
328	  req->dispatched = now;
329	  switch (req->action) {
330	  case UDPT_ACT_CONNECT: {
331	    connectionIdCache_[std::make_pair(req->remoteAddr, req->remotePort)] =
332	        UDPTrackerConnection();
333	    break;
334	  }
335	  }
336	  inflightRequests_.push_back(req);
337	  pendingRequests_.pop_front();
338	}
