340	void UDPTrackerClient::requestFail(int error)
341	{
342	  if (pendingRequests_.empty()) {
343	    A2_LOG_WARN("pendingRequests_ is empty");
344	    return;
345	  }
346	  const std::shared_ptr<UDPTrackerRequest>& req = pendingRequests_.front();
347	  switch (req->action) {
348	  case UDPT_ACT_CONNECT:
349	    A2_LOG_INFO(fmt("UDPT fail CONNECT to %s:%u transaction_id=%08x",
350	                    req->remoteAddr.c_str(), req->remotePort,
351	                    req->transactionId));
352	    failConnect(req->remoteAddr, req->remotePort, error);
353	    break;
354	  case UDPT_ACT_ANNOUNCE:
355	    A2_LOG_INFO(fmt("UDPT fail ANNOUNCE to %s:%u transaction_id=%08x, "
356	                    "connection_id=%016" PRIx64 ", event=%s, infohash=%s",
357	                    req->remoteAddr.c_str(), req->remotePort,
358	                    req->transactionId, req->connectionId,
359	                    getUDPTrackerEventStr(req->event),
360	                    util::toHex(req->infohash).c_str()));
361	    break;
362	  default:
363	    // unreachable
364	    assert(0);
365	  }
366	  req->state = UDPT_STA_COMPLETE;
367	  req->error = error;
368	  pendingRequests_.pop_front();
369	}
