454	void UDPTrackerClient::handleTimeout(const Timer& now)
455	{
456	  std::vector<std::shared_ptr<UDPTrackerRequest>> dest;
457	  inflightRequests_.erase(std::remove_if(inflightRequests_.begin(),
458	                                         inflightRequests_.end(),
459	                                         TimeoutCheck(dest, this, now)),
460	                          inflightRequests_.end());
461	  pendingRequests_.insert(pendingRequests_.begin(), dest.begin(), dest.end());
462	}
