484	UDPTrackerConnection*
485	UDPTrackerClient::getConnectionId(const std::string& remoteAddr,
486	                                  uint16_t remotePort, const Timer& now)
487	{
488	  auto i = connectionIdCache_.find(std::make_pair(remoteAddr, remotePort));
489	  if (i == connectionIdCache_.end()) {
490	    return nullptr;
491	  }
492	  if ((*i).second.state == UDPT_CST_CONNECTED &&
493	      (*i).second.lastUpdated.difference(now) > 1_min) {
494	    connectionIdCache_.erase(i);
495	    return nullptr;
496	  }
497	  else {
498	    return &(*i).second;
499	  }
500	}
