namespace aria2 {

enum UDPTrackerAction {
  UDPT_ACT_CONNECT = 0,
  UDPT_ACT_ANNOUNCE = 1,
  UDPT_ACT_SCRAPE = 2,
  UDPT_ACT_ERROR = 3
};

enum UDPTrackerError {
  UDPT_ERR_SUCCESS,
  UDPT_ERR_TRACKER,
  UDPT_ERR_TIMEOUT,
  UDPT_ERR_NETWORK,
  UDPT_ERR_SHUTDOWN
};

enum UDPTrackerState { UDPT_STA_PENDING, UDPT_STA_COMPLETE };

enum UDPTrackerEvent {
  UDPT_EVT_NONE = 0,
  UDPT_EVT_COMPLETED = 1,
  UDPT_EVT_STARTED = 2,
  UDPT_EVT_STOPPED = 3
};

struct UDPTrackerReply {
  int32_t action;
  uint32_t transactionId;
  int32_t interval;
  int32_t leechers;
  int32_t seeders;
  std::vector<std::pair<std::string, uint16_t>> peers;
  UDPTrackerReply();
};

struct UDPTrackerRequest {
  std::string remoteAddr;
  uint16_t remotePort;
  uint64_t connectionId;
