63	void AnnounceList::reconfigure(
64	    const std::vector<std::vector<std::string>>& announceList)
65	{
66	  for (const auto& vec : announceList) {
67	    if (vec.empty()) {
68	      continue;
69	    }
70	
71	    std::deque<std::string> uris(std::begin(vec), std::end(vec));
72	    auto tier = std::make_shared<AnnounceTier>(std::move(uris));
73	    tiers_.push_back(std::move(tier));
74	  }
75	  resetIterator();
76	}
