78	void AnnounceList::reconfigure(const std::string& url)
79	{
80	  std::deque<std::string> urls{url};
81	  tiers_.push_back(std::make_shared<AnnounceTier>(std::move(urls)));
82	  resetIterator();
83	}
84	
85	void AnnounceList::resetIterator()
86	{
87	  currentTier_ = std::begin(tiers_);
88	  if (currentTier_ != std::end(tiers_) && (*currentTier_)->urls.size()) {
89	    currentTracker_ = std::begin((*currentTier_)->urls);
90	    currentTrackerInitialized_ = true;
91	  }
92	  else {
93	    currentTrackerInitialized_ = false;
94	  }
95	}
96	
97	std::string AnnounceList::getAnnounce() const
98	{
99	  if (currentTrackerInitialized_) {
100	    return *currentTracker_;
101	  }
102	  else {
103	    return A2STR::NIL;
104	  }
105	}
106	
107	void AnnounceList::announceSuccess()
108	{
109	  if (currentTrackerInitialized_) {
110	    (*currentTier_)->nextEvent();
111	    auto url = *currentTracker_;
112	    (*currentTier_)->urls.erase(currentTracker_);
113	    (*currentTier_)->urls.push_front(std::move(url));
114	    currentTier_ = std::begin(tiers_);
115	    currentTracker_ = std::begin((*currentTier_)->urls);
116	  }
117	}
118	
119	void AnnounceList::announceFailure()
120	{
121	  if (currentTrackerInitialized_) {
122	    ++currentTracker_;
123	    if (currentTracker_ == std::end((*currentTier_)->urls)) {
124	      // force next event
125	      (*currentTier_)->nextEventIfAfterStarted();
126	      ++currentTier_;
127	      if (currentTier_ == std::end(tiers_)) {
128	        currentTrackerInitialized_ = false;
129	      }
130	      else {
131	        currentTracker_ = std::begin((*currentTier_)->urls);
132	      }
133	    }
134	  }
135	}
