138	{
139	  if (currentTrackerInitialized_) {
140	    return (*currentTier_)->event;
141	  }
142	  else {
143	    return AnnounceTier::STARTED;
144	  }
145	}
146	
147	void AnnounceList::setEvent(AnnounceTier::AnnounceEvent event)
148	{
149	  if (currentTrackerInitialized_) {
150	    (*currentTier_)->event = event;
151	  }
152	}
153	
154	const char* AnnounceList::getEventString() const
155	{
156	  if (currentTrackerInitialized_) {
157	    switch ((*currentTier_)->event) {
158	    case AnnounceTier::STARTED:
159	    case AnnounceTier::STARTED_AFTER_COMPLETION:
160	      return "started";
161	    case AnnounceTier::STOPPED:
162	      return "stopped";
163	    case AnnounceTier::COMPLETED:
164	      return "completed";
165	    default:
166	      return "";
167	    }
168	  }
169	  else {
170	    return "";
171	  }
172	}
