174	namespace {
175	class FindStoppedAllowedTier {
176	public:
177	  bool operator()(const std::shared_ptr<AnnounceTier>& tier) const
178	  {
179	    switch (tier->event) {
180	    case AnnounceTier::DOWNLOADING:
181	    case AnnounceTier::STOPPED:
182	    case AnnounceTier::COMPLETED:
183	    case AnnounceTier::SEEDING:
184	      return true;
185	    default:
186	      return false;
187	    }
188	  }
189	};
190	} // namespace
191	
192	namespace {
193	class FindCompletedAllowedTier {
194	public:
195	  bool operator()(const std::shared_ptr<AnnounceTier>& tier) const
196	  {
197	    switch (tier->event) {
198	    case AnnounceTier::DOWNLOADING:
199	    case AnnounceTier::COMPLETED:
200	      return true;
201	    default:
202	      return false;
203	    }
204	  }
205	};
206	} // namespace
