208	size_t AnnounceList::countStoppedAllowedTier() const
209	{
210	  return count_if(std::begin(tiers_), std::end(tiers_),
211	                  FindStoppedAllowedTier());
212	}
213	
214	size_t AnnounceList::countCompletedAllowedTier() const
215	{
216	  return count_if(std::begin(tiers_), std::end(tiers_),
217	                  FindCompletedAllowedTier());
218	}
