220	void AnnounceList::setCurrentTier(
221	    std::deque<std::shared_ptr<AnnounceTier>>::iterator itr)
222	{
223	  if (itr != std::end(tiers_)) {
224	    currentTier_ = std::move(itr);
225	    currentTracker_ = std::begin((*currentTier_)->urls);
226	  }
