229	void AnnounceList::moveToStoppedAllowedTier()
230	{
231	  auto itr = find_wrap_if(std::begin(tiers_), std::end(tiers_), currentTier_,
232	                          FindStoppedAllowedTier());
233	  setCurrentTier(std::move(itr));
234	}
235	
236	void AnnounceList::moveToCompletedAllowedTier()
237	{
238	  auto itr = find_wrap_if(std::begin(tiers_), std::end(tiers_), currentTier_,
239	                          FindCompletedAllowedTier());
240	  setCurrentTier(std::move(itr));
241	}
