243	void AnnounceList::shuffle()
244	{
245	  for (const auto& tier : tiers_) {
246	    auto& urls = tier->urls;
247	    std::shuffle(std::begin(urls), std::end(urls),
248	                 *SimpleRandomizer::getInstance());
249	  }
250	}
251	
252	bool AnnounceList::allTiersFailed() const
253	{
254	  return currentTier_ == std::end(tiers_);
255	}
