/* copyright --> */
#ifndef D_ANNOUNCE_TIER_H
#define D_ANNOUNCE_TIER_H

#include "common.h"

#include <string>
#include <deque>

namespace aria2 {

class AnnounceTier {
public:
  enum AnnounceEvent {
    STARTED,
    STARTED_AFTER_COMPLETION,
    DOWNLOADING,
    STOPPED,
    COMPLETED,
    SEEDING,
    HALTED
  };

  AnnounceEvent event;
  std::deque<std::string> urls;

  AnnounceTier(std::deque<std::string> urls);

  ~AnnounceTier();

  // Don't allow copying
  AnnounceTier(const AnnounceTier&) = delete;
  AnnounceTier& operator=(const AnnounceTier&) = delete;

  void nextEvent();

  void nextEventIfAfterStarted();
};

} // namespace aria2

#endif // D_ANNOUNCE_TIER_H

